DO $$
DECLARE n int; missing int;
BEGIN
  SELECT count(*) INTO n FROM public.rollback_20260901_manifest;
  IF n <> 205 THEN
    RAISE EXCEPTION 'manifest expected 205 rows, got %', n;
  END IF;
  SELECT count(*) INTO missing
    FROM public.rollback_20260901_manifest m
   WHERE NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = m.jobname);
  RAISE NOTICE 'manifest rows=% ; manifest jobs no longer present in cron.job=%', n, missing;
END $$;
